  ["e24d4df0c50146d4"] = { "Il ⟦Blackrock Mountain=Massiccio Roccianera⟧ si trova tra la ⟦Searing Gorge=Gorgia Rovente⟧ a nord e le ⟦Burning Steppes=Steppe Ardenti⟧ a sud.", "." },
