  ["e2b3e64d335a6c16"] = { "Salve, <ragazzo/ragazza>... mi chiamo Oglethorpe e potrei aver costruito io uno degli straordinari congegni gnomeschi che potresti avere! Se è esploso, allora non è opera mia; se invece ti ha reso <ricco/ricca>, possiamo parlare di diritti d'autore!\n\nAh, e se vieni da Gnomeregan, puoi prendere due angoli di novanta gradi, sbatterli insieme e metterti in marcia. Non ho niente da dirti.", "." },
  ["e2c28b2c2f1532f3"] = { "Le benedizioni della Madre Terra siano con te.", "." },
